/bin/bash -lc "python3 - <<'PY'
import ast,json,subprocess
from pathlib import Path
root=Path('/workspace')
p=json.loads((root/'proposal.json').read_text())
p['study']['hypothesis'] += ' All13 authorized execution receipts are successful and previous_runtime_error is null: the unsupported joint-pairing prediction is scientific counterevidence, not an execution failure. Raw parquet and Torch are not available in this coding context; accepted host baseline/data identities are inherited and a fresh empirical baseline cannot be rerun here.'
p['study']['predictions'].append('Host preflight, charged to the same ledger: instantiate every module with the real feature map; verify identical state_dict keys/shapes and parameter counts; finite four[B,1] probabilities and BCE gradients; empty histories; one event; all100 events; no positive feedback; overlapping feedback masks; zero/unknown category or brand; in-vocabulary masked-payload and masked-feedback perturbation invariance; ignore target action. Compare legacy and pooled_local after loading identical weights in eval mode, with TF32 disabled; check FP32 gradients on the same fixed-label diagnostic batch, then measure BF16 error separately. No scoring or training was performed locally.')
p['study']['contrasts'][0]['decision_if_supported']='Retain the compact implementation as an efficiency-frontier option if measured cost improves at stable repeated quality. Overall incumbent/final selection still uses the frozen macro-AUC rule and exact tie breakers, without an undeclared quality tolerance. Record arithmetic equivalence separately from empirical quality/cost.'
p['study']['cost_plan']['stop_rule'] += ' The proposal is the complete output for the current phase; dynamic correctness checks and training await the authorized host interface, which is not exposed in this workspace.'
(root/'proposal.json').write_text(json.dumps(p,ensure_ascii=False,indent=2)+'\\n')
r=json.loads(subprocess.check_output(['python3','/workspace/tools.py','resolve','run://r-001']))
def validate(v,s,path='"'$'"'):
 t=s.get('type')
 checks={'object':lambda x:isinstance(x,dict),'array':lambda x:isinstance(x,list),'string':lambda x:isinstance(x,str),'boolean':lambda x:isinstance(x,bool),'number':lambda x:isinstance(x,(int,float)) and not isinstance(x,bool),'integer':lambda x:isinstance(x,int) and not isinstance(x,bool),'null':lambda x:x is None}
 if t: assert checks[t](v),(path,'type',t)
 if 'enum' in s: assert v in s['enum'],(path,'enum')
 if 'const' in s: assert v==s['const'],(path,'const')
 if isinstance(v,dict):
  assert set(s.get('required',[]))<=set(v),(path,'required')
  props=s.get('properties',{})
  if s.get('additionalProperties') is False: assert set(v)<=set(props),(path,'additionalProperties')
  for k,x in v.items():
   if k in props: validate(x,props[k],path+'.'+k)
 if isinstance(v,list):
  assert len(v)>=s.get('minItems',0),(path,'minItems')
  if 'items' in s:
   for i,x in enumerate(v): validate(x,s['items'],path+'['+str(i)+']')
 if isinstance(v,str): assert len(v)>=s.get('minLength',0),(path,'minLength')
validate(p['study'],r['study_schema'])
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
for variant in p['variants']:
 assert set(variant)=={'name','file','role','config','note'}
 assert variant['role'] in ['candidate','control']
 tree=ast.parse((root/variant['file']).read_text())
 config=next(ast.literal_eval(n.value) for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets))
 assert config==variant['config']
assert any(v['role']=='candidate' for v in p['variants'])
for a in p['knowledge_assessments']:
 assert a['decision'] in ['used','considered','rejected','unresolved']
 assert set(a['variant_names'])<=set(v['name'] for v in p['variants'])
print('Complete recursive study-schema validation: PASS')
print('Four standalone variant files and literal configs: PASS')
print('Knowledge assessments:15; no source adoption or originality falsely asserted')
print('Current phase complete: proposal.json plus candidate modules; training and dynamic validation not run')
PY"

